func (r *StatefulSetAutoScalerReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    log := r.Log.WithValues("statefulsetautoscaler", req.NamespacedName)

    var scaler v1alpha1.StatefulSetAutoScaler
    if err := r.Get(ctx, req.NamespacedName, &scaler); err != nil {
        if apierrors.IsNotFound(err) {
            return ctrl.Result{}, nil
        }
        return ctrl.Result{}, err
    }

    var sts appsv1.StatefulSet
    stsKey := types.NamespacedName{Name: scaler.Spec.TargetRef.Name, Namespace: scaler.Namespace}
    if err := r.Get(ctx, stsKey, &sts); err != nil {
        log.Error(err, "failed to get target StatefulSet")
        r.Recorder.Eventf(&scaler, corev1.EventTypeWarning, "TargetNotFound", "StatefulSet %s not found", stsKey)
        return ctrl.Result{RequeueAfter: 30 * time.Second}, nil
    }

    metrics, err := r.MetricsClient.GetCurrentMetrics(ctx, sts.Namespace, sts.Name, scaler.Spec.Metrics)
    if err != nil {
        log.Error(err, "failed to fetch metrics")
        return ctrl.Result{RequeueAfter: 15 * time.Second}, nil
    }

    desired, reason, err := r.Calculator.ComputeDesiredReplicas(
        scaler.Spec.MinReplicas,
        scaler.Spec.MaxReplicas,
        *sts.Spec.Replicas,
        metrics,
        scaler.Spec.ScalingPolicies,
    )
    if err != nil {
        log.Error(err, "scaling calculation failed")
        return ctrl.Result{}, err
    }

    if desired == *sts.Spec.Replicas {
        log.V(1).Info("no scaling needed", "current", *sts.Spec.Replicas)
        return ctrl.Result{RequeueAfter: scaler.Spec.EvaluationInterval.Duration}, nil
    }

    if !r.isCooldownExpired(scaler, desired > *sts.Spec.Replicas) {
        log.Info("cooldown active, skipping scale", "desired", desired)
        return ctrl.Result{RequeueAfter: 10 * time.Second}, nil
    }

    pdb, err := r.findPDB(ctx, sts)
    if err == nil && pdb != nil {
        if !r.isPDBSafe(pdb, sts, desired) {
            log.Info("PDB would be violated, deferring scale-down")
            r.Recorder.Event(&scaler, corev1.EventTypeWarning, "PDBBlocked", "Scale-down blocked by PodDisruptionBudget")
            return ctrl.Result{RequeueAfter: 30 * time.Second}, nil
        }
    }

    patch := client.MergeFrom(sts.DeepCopy())
    sts.Spec.Replicas = &desired
    if err := r.Patch(ctx, &sts, patch); err != nil {
        log.Error(err, "failed to patch StatefulSet replicas")
        return ctrl.Result{}, err
    }

    scaler.Status.CurrentReplicas = *sts.Spec.Replicas
    scaler.Status.DesiredReplicas = desired
    scaler.Status.LastScaleTime = &metav1.Time{Time: time.Now()}
    scaler.Status.ScalingReason = reason
    if err := r.Status().Update(ctx, &scaler); err != nil {
        log.Error(err, "failed to update scaler status")
        return ctrl.Result{}, err
    }

    r.Recorder.Eventf(&scaler, corev1.EventTypeNormal, "Scaled", "Scaled StatefulSet %s from %d to %d: %s", stsKey, *sts.Spec.Replicas, desired, reason)
    log.Info("scaled StatefulSet", "from", *sts.Spec.Replicas, "to", desired, "reason", reason)
    return ctrl.Result{RequeueAfter: scaler.Spec.EvaluationInterval.Duration}, nil
}

Great catches, especially the race on sts.Spec.Replicas — embarrassing. I'll fix all of those. Now here's the scaling calculator. This is the core logic that determines replica count from metrics. Referring back to your point in turn 4 about the union approach for thresholds, I've updated the struct but the calculator still uses a single code path:

func (c *Calculator) ComputeDesiredReplicas(
    minReplicas, maxReplicas, currentReplicas int32,
    metrics []MetricValue,
    policies []v1alpha1.ScalingPolicy,
) (int32, string, error) {
    if len(metrics) == 0 {
        return currentReplicas, "no metrics available", nil
    }

    var candidates []scalingCandidate
    for _, policy := range policies {
        metric, found := findMetric(metrics, policy.MetricName)
        if !found {
            continue
        }

        var threshold float64
        if policy.ResourceThreshold != nil {
            threshold = policy.ResourceThreshold.AsApproximateFloat64()
        } else if policy.ThresholdValue != nil {
            threshold = *policy.ThresholdValue
        } else {
            return 0, "", fmt.Errorf("policy %s has no threshold", policy.MetricName)
        }

        if threshold <= 0 {
            return 0, "", fmt.Errorf("policy %s has non-positive threshold %f", policy.MetricName, threshold)
        }

        ratio := metric.Value / threshold
        rawDesired := math.Ceil(float64(currentReplicas) * ratio)
        desired := int32(rawDesired)

        if policy.ScaleUpBehavior != nil && desired > currentReplicas {
            maxIncrease := int32(math.Ceil(float64(currentReplicas) * policy.ScaleUpBehavior.MaxPercentIncrease / 100))
            if desired-currentReplicas > maxIncrease {
                desired = currentReplicas + maxIncrease
            }
        }

        if policy.ScaleDownBehavior != nil && desired < currentReplicas {
            maxDecrease := int32(math.Ceil(float64(currentReplicas) * policy.ScaleDownBehavior.MaxPercentDecrease / 100))
            if currentReplicas-desired > maxDecrease {
                desired = currentReplicas - maxDecrease
            }
        }

        candidates = append(candidates, scalingCandidate{
            desired:    desired,
            metricName: policy.MetricName,
            ratio:      ratio,
        })
    }

    if len(candidates) == 0 {
        return currentReplicas, "no matching policies", nil
    }

    best := candidates[0]
    for _, c := range candidates[1:] {
        if c.desired > best.desired {
            best = c
        }
    }

    desired := clamp(best.desired, minReplicas, maxReplicas)
    reason := fmt.Sprintf("metric %s ratio %.2f -> %d replicas", best.metricName, best.ratio, desired)
    return desired, reason, nil
}

The int32 overflow is scary — good catch. For the scale-down strategy, we intentionally want max-of-all (HPA-style) but I'll add the doc comment. Now here's the webhook validation. This ties back to your turn 2 comment about admission-time validation. I've also added the defaulting webhook:

func (v *StatefulSetAutoScalerValidator) ValidateCreate(ctx context.Context, obj runtime.Object) (admission.Warnings, error) {
    scaler := obj.(*v1alpha1.StatefulSetAutoScaler)
    var allErrs field.ErrorList

    specPath := field.NewPath("spec")

    if scaler.Spec.MinReplicas < 0 {
        allErrs = append(allErrs, field.Invalid(specPath.Child("minReplicas"), scaler.Spec.MinReplicas, "must be >= 0"))
    }
    if scaler.Spec.MaxReplicas < scaler.Spec.MinReplicas {
        allErrs = append(allErrs, field.Invalid(specPath.Child("maxReplicas"), scaler.Spec.MaxReplicas, "must be >= minReplicas"))
    }
    if scaler.Spec.MaxReplicas > 1000 {
        allErrs = append(allErrs, field.Invalid(specPath.Child("maxReplicas"), scaler.Spec.MaxReplicas, "exceeds safety limit of 1000"))
    }

    policiesPath := specPath.Child("scalingPolicies")
    if len(scaler.Spec.ScalingPolicies) == 0 {
        allErrs = append(allErrs, field.Required(policiesPath, "at least one scaling policy required"))
    }

    seenMetrics := make(map[string]bool)
    for i, policy := range scaler.Spec.ScalingPolicies {
        pPath := policiesPath.Index(i)
        if policy.MetricName == "" {
            allErrs = append(allErrs, field.Required(pPath.Child("metricName"), "metric name required"))
        }
        if seenMetrics[policy.MetricName] {
            allErrs = append(allErrs, field.Duplicate(pPath.Child("metricName"), policy.MetricName))
        }
        seenMetrics[policy.MetricName] = true

        if policy.ResourceThreshold == nil && policy.ThresholdValue == nil {
            allErrs = append(allErrs, field.Required(pPath.Child("threshold"), "either resourceThreshold or thresholdValue required"))
        }
        if policy.ResourceThreshold != nil && policy.ThresholdValue != nil {
            allErrs = append(allErrs, field.Invalid(pPath.Child("threshold"), "both set", "only one of resourceThreshold or thresholdValue allowed"))
        }

        if policy.ScaleUpBehavior != nil && policy.ScaleUpBehavior.MaxPercentIncrease <= 0 {
            allErrs = append(allErrs, field.Invalid(pPath.Child("scaleUpBehavior", "maxPercentIncrease"), policy.ScaleUpBehavior.MaxPercentIncrease, "must be > 0"))
        }
        if policy.ScaleDownBehavior != nil && policy.ScaleDownBehavior.MaxPercentDecrease <= 0 {
            allErrs = append(allErrs, field.Invalid(pPath.Child("scaleDownBehavior", "maxPercentDecrease"), policy.ScaleDownBehavior.MaxPercentDecrease, "must be > 0"))
        }
    }

    if scaler.Spec.EvaluationInterval.Duration < 10*time.Second {
        allErrs = append(allErrs, field.Invalid(specPath.Child("evaluationInterval"), scaler.Spec.EvaluationInterval.Duration, "must be >= 10s"))
    }
    if scaler.Spec.EvaluationInterval.Duration > 10*time.Minute {
        allErrs = append(allErrs, field.Invalid(specPath.Child("evaluationInterval"), scaler.Spec.EvaluationInterval.Duration, "must be <= 10m"))
    }

    if len(allErrs) > 0 {
        return nil, apierrors.NewInvalid(scaler.GroupVersionKind().GroupKind(), scaler.Name, allErrs)
    }
    return nil, nil
}

func (v *StatefulSetAutoScalerValidator) ValidateUpdate(ctx context.Context, oldObj, newObj runtime.Object) (admission.Warnings, error) {
    return v.ValidateCreate(ctx, newObj)
}

The immutable targetRef is a great point — definitely need that. For minReplicas=0, we actually want to support scale-to-zero for dev environments, so I'll add the admission warning approach. Now let's look at the tests. Referring back to the calculator issues from turn 8 (overflow, missing metrics), here are the test cases:

func TestComputeDesiredReplicas(t *testing.T) {
    tests := []struct {
        name             string
        minReplicas      int32
        maxReplicas      int32
        currentReplicas  int32
        metrics          []MetricValue
        policies         []v1alpha1.ScalingPolicy
        expectedReplicas int32
        expectedReason   string
        expectErr        bool
    }{
        {
            name:            "scale up on high CPU",
            minReplicas:     1,
            maxReplicas:     10,
            currentReplicas: 3,
            metrics:         []MetricValue{{Name: "cpu", Value: 0.8}},
            policies:        []v1alpha1.ScalingPolicy{{MetricName: "cpu", ResourceThreshold: resource.NewMilliQuantity(500, resource.DecimalSI)}},
            expectedReplicas: 5, // ceil(3 * 0.8/0.5) = ceil(4.8) = 5
            expectedReason:   "metric cpu ratio 1.60 -> 5 replicas",
        },
        {
            name:            "scale down on low CPU",
            minReplicas:     1,
            maxReplicas:     10,
            currentReplicas: 6,
            metrics:         []MetricValue{{Name: "cpu", Value: 0.2}},
            policies:        []v1alpha1.ScalingPolicy{{MetricName: "cpu", ResourceThreshold: resource.NewMilliQuantity(500, resource.DecimalSI)}},
            expectedReplicas: 3, // ceil(6 * 0.2/0.5) = ceil(2.4) = 3
            expectedReason:   "metric cpu ratio 0.40 -> 3 replicas",
        },
        {
            name:            "respects maxReplicas",
            minReplicas:     1,
            maxReplicas:     5,
            currentReplicas: 3,
            metrics:         []MetricValue{{Name: "cpu", Value: 0.95}},
            policies:        []v1alpha1.ScalingPolicy{{MetricName: "cpu", ResourceThreshold: resource.NewMilliQuantity(200, resource.DecimalSI)}},
            expectedReplicas: 5, // ceil(3 * 0.95/0.2) = ceil(14.25) = 15, clamped to 5
        },
        {
            name:            "respects minReplicas",
            minReplicas:     2,
            maxReplicas:     10,
            currentReplicas: 5,
            metrics:         []MetricValue{{Name: "cpu", Value: 0.05}},
            policies:        []v1alpha1.ScalingPolicy{{MetricName: "cpu", ResourceThreshold: resource.NewMilliQuantity(500, resource.DecimalSI)}},
            expectedReplicas: 2, // ceil(5 * 0.05/0.5) = ceil(0.5) = 1, clamped to 2
        },
        {
            name:            "no metrics returns current",
            minReplicas:     1,
            maxReplicas:     10,
            currentReplicas: 3,
            metrics:         []MetricValue{},
            policies:        []v1alpha1.ScalingPolicy{{MetricName: "cpu"}},
            expectedReplicas: 3,
            expectedReason:   "no metrics available",
        },
        {
            name:            "zero threshold returns error",
            minReplicas:     1,
            maxReplicas:     10,
            currentReplicas: 3,
            metrics:         []MetricValue{{Name: "cpu", Value: 0.5}},
            policies:        []v1alpha1.ScalingPolicy{{MetricName: "cpu", ThresholdValue: floatPtr(0)}},
            expectErr:        true,
        },
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            c := &Calculator{}
            replicas, reason, err := c.ComputeDesiredReplicas(tt.minReplicas, tt.maxReplicas, tt.currentReplicas, tt.metrics, tt.policies)
            if tt.expectErr {
                assert.Error(t, err)
                return
            }
            assert.NoError(t, err)
            assert.Equal(t, tt.expectedReplicas, replicas)
            if tt.expectedReason != "" {
                assert.Equal(t, tt.expectedReason, reason)
            }
        })
    }
}

These are all excellent additions, I'll add them. Let me also show you the PDB-aware scaling logic since you flagged the error swallowing in turn 6. I've refactored it based on your feedback:

func (r *StatefulSetAutoScalerReconciler) findPDB(ctx context.Context, sts appsv1.StatefulSet) (*policyv1.PodDisruptionBudget, error) {
    var pdbList policyv1.PodDisruptionBudgetList
    if err := r.List(ctx, &pdbList, client.InNamespace(sts.Namespace)); err != nil {
        return nil, fmt.Errorf("listing PDBs in namespace %s: %w", sts.Namespace, err)
    }

    stsLabels := sts.Spec.Selector.MatchLabels
    for i := range pdbList.Items {
        pdb := &pdbList.Items[i]
        selector, err := metav1.LabelSelectorAsSelector(pdb.Spec.Selector)
        if err != nil {
            r.Log.Error(err, "invalid PDB selector", "pdb", pdb.Name)
            continue
        }
        if selector.Matches(labels.Set(stsLabels)) {
            return pdb, nil
        }
    }
    return nil, nil
}

func (r *StatefulSetAutoScalerReconciler) isPDBSafe(pdb *policyv1.PodDisruptionBudget, sts appsv1.StatefulSet, desiredReplicas int32) bool {
    currentHealthy := pdb.Status.CurrentHealthy
    disruptionsAllowed := pdb.Status.DisruptionsAllowed

    if desiredReplicas >= *sts.Spec.Replicas {
        return true // scale-up never violates PDB
    }

    reduction := *sts.Spec.Replicas - desiredReplicas

    // Check if the scale-down would reduce healthy pods below what PDB allows
    if reduction > disruptionsAllowed {
        r.Log.Info("PDB would block scale-down",
            "pdb", pdb.Name,
            "currentHealthy", currentHealthy,
            "disruptionsAllowed", disruptionsAllowed,
            "requestedReduction", reduction,
        )
        return false
    }

    // Also check minAvailable if set
    if pdb.Spec.MinAvailable != nil {
        minAvail, err := intstr.GetScaledValueFromIntOrPercent(pdb.Spec.MinAvailable, int(*sts.Spec.Replicas), true)
        if err != nil {
            r.Log.Error(err, "failed to parse PDB minAvailable")
            return false // fail closed
        }
        afterScaleDown := currentHealthy - reduction
        if afterScaleDown < int32(minAvail) {
            r.Log.Info("scale-down would violate PDB minAvailable",
                "minAvailable", minAvail,
                "afterScaleDown", afterScaleDown,
            )
            return false
        }
    }

    return true
}

Multiple PDB matching is a good edge case I hadn't considered. I'll add a loop to find the most restrictive. Now let me show you the RBAC and leader election setup. Referring back to the finalizer suggestion from turn 6, I've added that too:

func (r *StatefulSetAutoScalerReconciler) SetupWithManager(mgr ctrl.Manager) error {
    return ctrl.NewControllerManagedBy(mgr).
        For(&v1alpha1.StatefulSetAutoScaler{}).
        Owns(&appsv1.StatefulSet{}).
        WithEventFilter(predicate.GenerationChangedPredicate{}).
        Complete(r)
}

// +kubebuilder:rbac:groups=autoscaling.example.io,resources=statefulsetautoscalers,verbs=get;list;watch;create;update;patch;delete
// +kubebuilder:rbac:groups=autoscaling.example.io,resources=statefulsetautoscalers/status,verbs=get;update;patch
// +kubebuilder:rbac:groups=autoscaling.example.io,resources=statefulsetautoscalers/finalizers,verbs=update
// +kubebuilder:rbac:groups=apps,resources=statefulsets,verbs=get;list;watch;update;patch
// +kubebuilder:rbac:groups=policy,resources=poddisruptionbudgets,verbs=get;list;watch
// +kubebuilder:rbac:groups="",resources=events,verbs=create;patch

const finalizerName = "autoscaling.example.io/statefulsetautoscaler-finalizer"

func (r *StatefulSetAutoScalerReconciler) handleFinalizer(ctx context.Context, scaler *v1alpha1.StatefulSetAutoScaler) (ctrl.Result, bool, error) {
    if scaler.ObjectMeta.DeletionTimestamp.IsZero() {
        if !controllerutil.ContainsFinalizer(scaler, finalizerName) {
            controllerutil.AddFinalizer(scaler, finalizerName)
            if err := r.Update(ctx, scaler); err != nil {
                return ctrl.Result{}, false, err
            }
        }
        return ctrl.Result{}, true, nil // continue reconciliation
    }

    // Object is being deleted
    if controllerutil.ContainsFinalizer(scaler, finalizerName) {
        // Cleanup: reset StatefulSet to its pre-autoscaler state if possible
        r.Log.Info("finalizer triggered, cleaning up", "scaler", scaler.Name)

        var sts appsv1.StatefulSet
        stsKey := types.NamespacedName{Name: scaler.Spec.TargetRef.Name, Namespace: scaler.Namespace}
        if err := r.Get(ctx, stsKey, &sts); err != nil {
            if !apierrors.IsNotFound(err) {
                return ctrl.Result{}, false, err
            }
            // StatefulSet already gone, nothing to clean up
        } else {
            // Remove any autoscaler annotations we added
            annotations := sts.GetAnnotations()
            delete(annotations, "autoscaling.example.io/managed-by")
            delete(annotations, "autoscaling.example.io/last-scale-time")
            sts.SetAnnotations(annotations)
            if err := r.Update(ctx, &sts); err != nil {
                r.Log.Error(err, "failed to clean annotations from StatefulSet")
                // Don't block deletion on annotation cleanup failure
            }
        }

        controllerutil.RemoveFinalizer(scaler, finalizerName)
        if err := r.Update(ctx, scaler); err != nil {
            return ctrl.Result{}, false, err
        }
    }

    return ctrl.Result{}, false, nil // stop reconciliation, object is deleting
}

The Owns vs Watches distinction is critical — I completely missed that. That would have been a production incident. Let me show you the last major piece: the metrics client and the integration test setup. This connects to the calculator (turn 7-8) and the metrics timeout issue you raised in turn 6:

type MetricsClient struct {
    metricsClient       metricsclient.MetricsClient
    customMetricsClient custommetrics.CustomMetricsClient
    timeout             time.Duration
}

func NewMetricsClient(config *rest.Config, timeout time.Duration) (*MetricsClient, error) {
    mc, err := metricsclient.NewForConfig(config)
    if err != nil {
        return nil, fmt.Errorf("creating metrics client: %w", err)
    }

    cmc, err := custommetrics.NewForConfig(config)
    if err != nil {
        return nil, fmt.Errorf("creating custom metrics client: %w", err)
    }

    if timeout == 0 {
        timeout = 10 * time.Second
    }

    return &MetricsClient{
        metricsClient:       mc,
        customMetricsClient: cmc,
        timeout:             timeout,
    }, nil
}

func (m *MetricsClient) GetCurrentMetrics(ctx context.Context, namespace, name string, metricSpecs []v1alpha1.MetricSpec) ([]MetricValue, error) {
    ctx, cancel := context.WithTimeout(ctx, m.timeout)
    defer cancel()

    var results []MetricValue
    var errs []error

    for _, spec := range metricSpecs {
        switch spec.Type {
        case v1alpha1.ResourceMetric:
            podMetrics, err := m.metricsClient.PodMetricses(namespace).Get(ctx, name, metav1.GetOptions{})
            if err != nil {
                errs = append(errs, fmt.Errorf("fetching resource metric %s: %w", spec.Name, err))
                continue
            }
            value := aggregatePodMetric(podMetrics, spec.Name)
            results = append(results, MetricValue{Name: spec.Name, Value: value, Timestamp: time.Now()})

        case v1alpha1.CustomMetric:
            metricValue, err := m.customMetricsClient.NamespacedMetrics(namespace).GetForObject(
                schema.GroupResource{Group: "apps", Resource: "statefulsets"},
                name,
                spec.Name,
                labels.Everything(),
            )
            if err != nil {
                errs = append(errs, fmt.Errorf("fetching custom metric %s: %w", spec.Name, err))
                continue
            }
            results = append(results, MetricValue{Name: spec.Name, Value: metricValue.Value.AsApproximateFloat64(), Timestamp: time.Now()})

        default:
            errs = append(errs, fmt.Errorf("unknown metric type %s for %s", spec.Type, spec.Name))
        }
    }

    if len(results) == 0 && len(errs) > 0 {
        return nil, fmt.Errorf("all metric fetches failed: %v", errors.Join(errs...))
    }

    if len(errs) > 0 {
        // Log partial failures but return what we have
        for _, err := range errs {
            klog.Warningf("partial metric fetch failure: %v", err)
        }
    }

    return results, nil
}
